(function(){'use strict';var reduced=!!(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches);var io=null;function fmtNum(val,digits){if(digits>0){return val.toFixed(digits);}
try{return Number(val.toFixed(0)).toLocaleString('zh-CN');}catch(e){return String(Math.round(val));}}
function runCount(el){if(el.classList.contains('done')){return;}
var raw=(el.getAttribute('data-count')||'').trim();if(raw===''){return;}
var target=parseFloat(raw);if(isNaN(target)){return;}
var hasDot=raw.indexOf('.')>=0;var digits=hasDot?(raw.split('.')[1]||'').length:0;if(reduced||typeof requestAnimationFrame==='undefined'){el.textContent=fmtNum(target,digits);el.classList.add('done');return;}
el.textContent='0';var dur=1200;var start=null;function step(ts){if(start===null){start=ts;}
var p=Math.min(1,(ts-start)/dur);var ease=1-Math.pow(1-p,3);el.textContent=fmtNum(target*ease,digits);if(p<1){requestAnimationFrame(step);}else{el.textContent=fmtNum(target,digits);el.classList.add('done');}}
requestAnimationFrame(step);}
function scan(scope){var root=scope&&scope.querySelectorAll?scope:document;var counts=root.querySelectorAll('.tri3-count[data-count]:not(.done)');Array.prototype.forEach.call(counts,function(el){if(reduced||typeof IntersectionObserver==='undefined'){runCount(el);return;}
var r=el.getBoundingClientRect();var vh=window.innerHeight||document.documentElement.clientHeight;if(r.top<vh&&r.bottom>0){runCount(el);}else if(io){io.observe(el);}});var bars=root.querySelectorAll('.stat-bars:not(.is-anim)');Array.prototype.forEach.call(bars,function(el){if(reduced||typeof IntersectionObserver==='undefined'){el.classList.add('is-anim');return;}
var r=el.getBoundingClientRect();var vh=window.innerHeight||document.documentElement.clientHeight;if(r.top<vh&&r.bottom>0){el.classList.add('is-anim');}else if(io){io.observe(el);}});}
function init(){if(typeof IntersectionObserver==='undefined'){return;}
if(io){return;}
io=new IntersectionObserver(function(entries){entries.forEach(function(en){if(!en.isIntersecting){return;}
var t=en.target;io.unobserve(t);if(t.classList.contains('tri3-count')){runCount(t);}else if(t.classList.contains('stat-bars')){t.classList.add('is-anim');}});},{rootMargin:'0px 0px -10% 0px'});}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',function(){init();scan();});}else{init();scan();}
document.addEventListener('tri3:render',function(){init();scan();});document.addEventListener('tri3:list-switch',function(){init();scan(document);});document.addEventListener('tri3:home-switch',function(){init();scan(document);});document.addEventListener('tri3:homelist',function(){init();scan(document);});window.Tri3Motion={update:function(scope){init();scan(scope);},runCount:runCount};})();